function step(n,dt,speed){let dx=n.tx-n.x,dy=n.ty-n.y,len=Math.hypot(dx,dy);if(len>2){let d=Math.min(len,speed*dt);n.x+=dx/len*d;n.y+=dy/len*d;return true}return false}/* PAW_VALLEY_CAMERA_BEGIN */
function pawValleyCameraBounds(w,h,worldHeight,scale,offset,foot,head){
 if(![w,h,worldHeight,scale,offset,foot,head].every(Number.isFinite)||Math.min(w,h,worldHeight,scale)<=0)return null;
 const height=worldHeight*scale;
 if(height<=h)return (h-height)/2;
 const lower=h-height,upper=0;
 const low=Math.max(head+15,h-115),high=Math.min(low,Math.max(80,head+15));
 const screenFoot=foot*scale+offset;
 if(screenFoot>low)offset-=screenFoot-low;else if(screenFoot<high)offset+=high-screenFoot;
 return Math.max(lower,Math.min(upper,offset))
}
